<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{getRanking,type RankRow}from'../services/ranking';import{rankingConfigured}from'../services/supabase';import{players}from'../stores';import{useI18n}from'../i18n';const rows=ref<RankRow[]>([]),loading=ref(rankingConfigured),{t}=useI18n(),localRows=computed(()=>[...players].sort((a,b)=>b.best-a.best));onMounted(async()=>{if(rankingConfigured)rows.value=await getRanking();loading.value=false})</script>
<template><section class="screen sub"><RouterLink to="/home" class="back">⌂ {{t('home')}}</RouterLink><h1>🏆 Classifica locale</h1><ol class="ranking local-ranking"><li v-for="(r,i) in localRows" :key="r.id"><b>{{i+1}}</b><span>{{r.nickname}}</span><strong>{{r.best}}</strong></li></ol><RouterLink to="/players" class="primary ranking-add">＋ AGGIUNGI GIOCATORE</RouterLink><h2>Classifica globale</h2><div v-if="!rankingConfigured" class="ranking-notice">Classifica globale non disponibile.</div><p v-else-if="loading">…</p><p v-else-if="!rows.length">{{t('noScores')}}</p><ol v-else class="ranking"><li v-for="(r,i) in rows" :key="`${r.nickname}-${i}`"><b>{{r.position??i+1}}</b><span>{{r.nickname}}</span><strong>{{r.best_score}}</strong></li></ol></section></template>
